import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.enableCors();
  await app.listen(5000);
}
bootstrap();
</CODE>

Make sure to create a directory named `uploads` in the root of your project to store the uploaded videos and extracted frames. You can run the application using the command `npm run start`, and it will start a web server on `0.0.0.0:5000`. 

This implementation includes input validation for the uploaded video and frame number, ensuring that the application handles errors gracefully and securely.

